import React from 'react';
// This pulls the data from the report file in the src folder
import impactReport from '../../community_impact_report.js'; // Adjusted path to step out of /spatial directory

const CardVeiwer = ({ zoom = 0, activeNode = null }) => {
    // Runs your generateVideoScript logic to get the report details
    const data = impactReport.generateVideoScript();

    // Determine card colors based on the active anchor node
    const getBorderColor = () => {
        if (activeNode === 'MEMBER_01_ARCHITECT') return '#00ffcc'; // Cyber Mint for AIDE
        if (activeNode === 'MEMBER_02_GUIDE') return '#3b82f6';     // Blue for The Guide
        return '#334155'; // Default muted state
    };

    return (
        <div style={{
            padding: '20px',
            display: 'flex',
            justifyContent: 'center',
            opacity: zoom > 0.2 ? (zoom * 1.2) : 0, // Card fades in as photon approaches
            transform: `translateY(${(1 - zoom) * 50}px)`, // Card rises upward during scroll zoom
            transition: 'transform 0.2s ease-out, opacity 0.2s ease-out',
            pointerEvents: 'auto'
        }}>
            <div style={{
                border: `1px solid ${getBorderColor()}`,
                borderRadius: '12px',
                padding: '24px',
                color: 'white',
                width: '100%',
                maxWidth: '400px',
                background: '#1e293b',
                boxShadow: activeNode ? `0 10px 30px ${getBorderColor()}33` : '0 10px 15px rgba(0,0,0,0.3)',
                transition: 'border 0.3s ease, box-shadow 0.3s ease'
            }}>
                <div style={{ color: getBorderColor(), fontWeight: 'bold', fontSize: '0.8rem', transition: 'color 0.3s ease' }}>
                    {activeNode ? `ACTIVE NODE: ${activeNode}` : impactReport.mission}
                </div>

                <h2 style={{ margin: '15px 0', fontSize: '1.4rem' }}>{data.headline}</h2>

                <div style={{
                    background: '#0f172a',
                    padding: '15px',
                    borderRadius: '8px',
                    borderLeft: `4px solid ${activeNode ? getBorderColor() : '#10b981'}`,
                    marginBottom: '20px',
                    transition: 'border-left 0.3s ease'
                }}>
                    <p style={{ margin: 0, fontSize: '0.8rem', color: '#64748b' }}>TOTAL DISTRIBUTED</p>
                    <p style={{ margin: '5px 0 0 0', fontSize: '1.8rem', fontWeight: 'bold', color: activeNode ? getBorderColor() : '#10b981', transition: 'color 0.3s ease' }}>
                        ${data.total_dimes_distributed.toLocaleString()}
                    </p>
                </div>

                <p style={{ lineHeight: '1.5', opacity: 0.9 }}>{data.message}</p>

                <div style={{
                    marginTop: '20px',
                    paddingTop: '15px',
                    borderTop: '1px solid #334155',
                    fontSize: '0.75rem',
                    display: 'flex',
                    justifyContent: 'space-between'
                }}>
                    <span style={{ color: getBorderColor(), transition: 'color 0.3s ease' }}>STABLE GROWTH</span>
                    <span style={{ color: '#64748b' }}>PAIDAI OFFICIAL</span>
                </div>
            </div>
        </div>
    );
};

export default CardVeiwer;
